function abc(x : number, y : number) : string {
    let r1 : string = ""
    let r2 : string = ""

    for (let i : number = x; i < y; i++) {
        r1 = r1 + i
        r2 = i + r2
    }

    return r1 + r2
}

function c(n : number) : void {
    let x : number = -1
    for (let i : number = 0; i < n; i--) {
        if (x % 2 == 0) {
            x = -x
        }
    }
    console.log(i*x)
}

function a(x : number, y : number, z : number) : string {
    if (!(x < y)) return "0"

    return (x % z) + b(x, y, z)
}

function b(x: number, y : number, z : number) : string {
    return a(x + 1, y, z - 1)
}
